#!/usr/bin/env bash
# Generate or verify metadata/frozen_inputs_checksums.tsv.
#
# Covers everything in the repository that is DATA rather than code and that
# cannot be regenerated by the pipeline:
#   data/frozen/    the Ensembl-114 metadata tables
#   provenance/     the verbatim upstream scripts and notebooks
#   metadata/       the sample sheets and manifests
#
# The point is that if any of these drift, a reviewer can tell. The FASTQ
# checksums are separate and live in metadata/fastq_md5_checksums.txt.

set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../.." || exit 1

OUT="metadata/frozen_inputs_checksums.tsv"
MODE="generate"
[ "${1:-}" = "--verify" ] && MODE="verify"
[ "${1:-}" = "--help" ] && { sed -n '2,13p' "$0"; exit 0; }

collect() {
  printf "path\tbytes\tmd5\n"
  find data/frozen provenance metadata -type f \
       ! -name 'frozen_inputs_checksums.tsv' \
       ! -name '*.md5' 2>/dev/null \
    | LC_ALL=C sort \
    | while IFS= read -r f; do
        printf "%s\t%s\t%s\n" "$f" "$(stat -c%s "$f")" "$(md5sum "$f" | cut -d' ' -f1)"
      done
}

if [ "$MODE" = "generate" ]; then
  collect > "$OUT"
  echo "[checksums] wrote $OUT ($(( $(wc -l < "$OUT") - 1 )) files)"
else
  if [ ! -f "$OUT" ]; then
    echo "[ERROR] $OUT not found. Run without --verify first." >&2
    exit 1
  fi
  TMP="$(mktemp)"; trap 'rm -f "$TMP"' EXIT
  collect > "$TMP"
  if diff -u "$OUT" "$TMP" > /dev/null; then
    echo "[checksums] PASS - all $(( $(wc -l < "$OUT") - 1 )) files match"
  else
    echo "[checksums] FAILED - the tree differs from $OUT:"
    diff -u "$OUT" "$TMP" | sed -n '4,60p' | sed 's/^/  /'
    exit 1
  fi
fi
